package com.termux.app.workspace;
import android.app.*;import android.content.*;import android.content.pm.*;import android.speech.*;import android.widget.*;import android.os.*;import android.provider.Settings;import org.junit.*;import static org.junit.Assert.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import org.robolectric.shadow.api.Shadow;import java.util.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,shadows=AgentSpeechServiceTest.Engine.class) public class AgentSpeechServiceTest {
 @Implements(SpeechRecognizer.class) public static class Engine {static RecognitionListener listener;static int starts,destroys,stops,cancels;static boolean available=true;@Implementation protected static boolean isRecognitionAvailable(Context c){return available;}@Implementation protected static SpeechRecognizer createSpeechRecognizer(Context c){return Shadow.newInstanceOf(SpeechRecognizer.class);}@Implementation protected static SpeechRecognizer createSpeechRecognizer(Context c,ComponentName n){throw new AssertionError("No explicit provider");}@Implementation protected void setRecognitionListener(RecognitionListener l){listener=l;}@Implementation protected void startListening(Intent i){assertTrue(i.getBooleanExtra(RecognizerIntent.EXTRA_PARTIAL_RESULTS,false));starts++;}@Implementation protected void stopListening(){stops++;}@Implementation protected void cancel(){cancels++;}@Implementation protected void destroy(){destroys++;}}
 static void configure(Activity a){Engine.available=true;Settings.Secure.putString(a.getContentResolver(),"voice_recognition_service","system.speech/.Service");ServiceInfo info=Shadows.shadowOf(a.getPackageManager()).addServiceIfNotPresent(new ComponentName("system.speech","system.speech.Service"));info.enabled=true;info.exported=true;info.applicationInfo.enabled=true;Shadows.shadowOf(a.getPackageManager()).addOrUpdateService(info);Shadows.shadowOf((Application)a.getApplication()).grantPermissions(android.Manifest.permission.RECORD_AUDIO);}
 static Bundle words(String text){Bundle b=new Bundle();b.putStringArrayList(SpeechRecognizer.RESULTS_RECOGNITION,new ArrayList<>(Arrays.asList(text)));return b;}
 @Before public void reset(){Engine.starts=Engine.destroys=Engine.stops=Engine.cancels=0;Engine.available=true;}
 @Test public void partialIsPreviewAndFinalAppendsOnlyOnceWithoutExternalActivity(){Activity a=Robolectric.buildActivity(Activity.class).setup().get();configure(a);EditText input=new EditText(a);input.setText("draft");input.setSelection(0,input.length());List<String> notices=new ArrayList<>(),states=new ArrayList<>();AgentDictation d=new AgentDictation(a,input,()->"one",notices::add);d.presentation((text,active,stop,cancel)->states.add(text));d.start();d.start();assertEquals(1,Engine.starts);assertNull(Shadows.shadowOf(a).getNextStartedActivityForResult());RecognitionListener listener=Engine.listener;listener.onReadyForSpeech(new Bundle());listener.onPartialResults(words("first"));listener.onPartialResults(words("first words"));assertEquals("draft",input.getText().toString());assertTrue(states.get(states.size()-1).contains("first words"));d.stop();assertEquals(1,Engine.stops);listener.onResults(words("first words"));listener.onResults(words("duplicate"));assertEquals("draft first words",input.getText().toString());assertTrue(Engine.destroys>0);assertTrue(notices.isEmpty());}
 @Test public void errorCancelSwitchAndEditedDraftRetainText(){Activity a=Robolectric.buildActivity(Activity.class).setup().get();configure(a);EditText input=new EditText(a);input.setText("keep");String[] owner={"one"};List<String> notices=new ArrayList<>();AgentDictation d=new AgentDictation(a,input,()->owner[0],notices::add);d.start();RecognitionListener old=Engine.listener;d.clear();d.start();old.onResults(words("late"));assertEquals("keep",input.getText().toString());Engine.listener.onError(SpeechRecognizer.ERROR_NETWORK);assertEquals(1,notices.size());assertEquals("keep",input.getText().toString());d.start();owner[0]="two";d.ownerChanged();Engine.listener.onResults(words("wrong chat"));assertEquals("keep",input.getText().toString());d.start();input.setText("edited");Engine.listener.onResults(words("discard"));assertEquals("edited",input.getText().toString());d.start();d.background();Engine.listener.onResults(words("hidden"));assertEquals("edited",input.getText().toString());}
 @Test public void missingDefaultDisabledAndPermissionDenialAreDistinct(){Activity a=Robolectric.buildActivity(Activity.class).setup().get();EditText input=new EditText(a);input.setText("keep");List<String> notices=new ArrayList<>();AgentDictation d=new AgentDictation(a,input,()->"one",notices::add);Settings.Secure.putString(a.getContentResolver(),"voice_recognition_service",null);d.start();assertEquals(0,Engine.starts);assertEquals(1,notices.size());configure(a);Engine.available=false;d.start();assertEquals(2,notices.size());Engine.available=true;Shadows.shadowOf((Application)a.getApplication()).denyPermissions(android.Manifest.permission.RECORD_AUDIO);d.start();d.permissionResult(AgentDictation.AUDIO_REQUEST);assertEquals(3,notices.size());assertEquals(0,Engine.starts);assertEquals("keep",input.getText().toString());d.start();Shadows.shadowOf((Application)a.getApplication()).grantPermissions(android.Manifest.permission.RECORD_AUDIO);d.permissionResult(AgentDictation.AUDIO_REQUEST);assertEquals(1,Engine.starts);d.clear();}
}
